// An existing message was edited.
message MessageEdited {
  string message_guid = 1;

  MessageContent content = 2;

  google.protobuf.Timestamp edited_at = 3;
}

// A message originally sent by the local user was read.
message MessageRead {
  string message_guid = 1;

  google.protobuf.Timestamp read_at = 2;
}

// A message was retracted.
message MessageUnsent {
  string message_guid = 1;

  google.protobuf.Timestamp retracted_at = 2;
}

message MessageReactionAdded {
  string message_guid = 1;

  optional int32 target_part_index = 2;

  MessageReaction reaction = 3;
}

message MessageReactionRemoved {
  string message_guid = 1;

  optional int32 target_part_index = 2;

  MessageReaction reaction = 3;
}

message StickerPlaced {
  string message_guid = 1;

  optional int32 target_part_index = 2;

  optional AttachmentInfo sticker = 3;

  optional StickerPlacement placement = 4;
}

// A discrete state transition observed for a message.
message MessageChangeEvent {
  string chat_guid = 1;

  google.protobuf.Timestamp occurred_at = 2;

  optional SingleServiceAddressInfo actor = 3;

  bool is_from_me = 4;

  oneof change {
    MessageReceived message_received = 10;

    MessageEdited message_edited = 11;

    MessageRead message_read = 12;

    MessageUnsent message_unsent = 13;

    MessageReactionAdded reaction_added = 14;

    MessageReactionRemoved reaction_removed = 15;

    StickerPlaced sticker_placed = 16;
  }
}

