## 1. `packages/core/src/content/` — full file list + the authoring convention

24 files:

```
app.ts  attachment.ts  avatar.ts  contact.ts  custom.ts  edit.ts  effect.ts
group.ts  markdown.ts  membership.ts  poll.ts  reaction.ts  read.ts  rename.ts
reply.ts  resolve.ts  richlink.ts  stream-text.ts  text.ts  types.ts
typing.ts  unsend.ts  voice.ts
```
(`resolve.ts` and `types.ts` are infrastructure, not content arms.)

### The convention, distilled

Every content file follows the same 4-part shape:
1. `xSchema = z.object({ type: z.literal("x"), ...fields })` — with the **doc comment attached to the schema**, not the builder, when the type is bidirectional/conceptual.
2. `export type X = z.infer<typeof xSchema>`
3. `export const asX = (input) => xSchema.parse({ type: "x", ...input })` — the **provider-facing** factory (fully-resolved inputs), exported via `authoring.ts`.
4. `export function x(...): ContentBuilder` — the **consumer-facing** builder returning `{ build: async () => ... }`, exported via `index.ts`.

Note: `asX` is *not* universal. `typing.ts` has `isTyping` instead; `rename.ts` and `membership.ts` have no `asX` (they parse inline); `text.ts`/`custom.ts` take a positional arg rather than an object.

### `packages/core/src/content/reaction.ts` (complete, 69 lines)

Notable: it's the only content type with a **narrowed builder interface** (`ReactionBuilder`) so `space.send` can overload on it.

```ts
// reaction.ts:1-13
import z from "zod";
import type { Message } from "../types/message";
import type { ContentBuilder } from "./types";

/**
 * A `ContentBuilder` whose build is statically known to produce `Reaction`
 * content. `space.send` overloads on this so `space.send(reaction(...))`
 * returns a Message with `content` narrowed to `Reaction`, matching
 * `message.react()`.
 */
export interface ReactionBuilder extends ContentBuilder {
  build(): Promise<Reaction>;
}
```

```ts
// reaction.ts:15-31
const isMessage = (v: unknown): v is Message =>
  typeof v === "object" && v !== null && "id" in v && "content" in v;

export const reactionSchema = z.object({
  type: z.literal("reaction"),
  emoji: z.string().min(1),
  target: z.custom<Message>(isMessage, {
    message: "reaction target must be a Message",
  }),
});

export type Reaction = z.infer<typeof reactionSchema>;

export const asReaction = (input: {
  emoji: string;
  target: Message;
}): Reaction => reactionSchema.parse({ type: "reaction", ...input });
```

```ts
// reaction.ts:33-69
/**
 * Construct a `reaction` content value targeting the given message.
 *
 * `space.send(reaction(emoji, message))` is the canonical form of
 * `message.react(emoji)`. It resolves to the reaction `Message`
 * (`content.type === "reaction"`) — keep it as the handle to `unsend()`
 * later. Resolves `undefined` only when the platform does not support
 * reactions (warned and skipped).
 *
 * Accepts `Message | undefined` so `space.send` results chain without
 * narrowing (`send` resolves `undefined` when a platform skips unsupported
 * content); an undefined target throws at build time.
 *
 * To react to a message known only by id, resolve it first via
 * `space.getMessage(id)`.
 */
export function reaction(
  emoji: string,
  target: Message | undefined
): ReactionBuilder {
  return {
    build: async () => {
      if (!target) {
        throw new Error(
          "reaction() target is undefined — the targeted message was never sent (space.send resolves undefined when a platform skips unsupported content)"
        );
      }
      // Reacting to a reaction is universally nonsensical — guard against it
      // mirroring `reply()`'s reject-list. Replies and group items are valid
      // reaction targets (real chat clients allow both), so only reject this.
      if (target.content.type === "reaction") {
        throw new Error('reaction() cannot target "reaction" content');
      }
      return asReaction({ emoji, target });
    },
  };
}
```

### `packages/core/src/content/read.ts` (complete, 61 lines) — your closest template

```ts
// read.ts:1-38
import z from "zod";
import type { Message } from "../types/message";
import type { ContentBuilder } from "./types";

const isMessage = (v: unknown): v is Message =>
  typeof v === "object" && v !== null && "id" in v && "content" in v;

/**
 * A `read` marks the conversation as read **up to** `target`, surfacing a
 * read receipt to the sender where the platform supports one.
 *
 * `space.send(read(message))` is the canonical outbound API;
 * `message.read()` and `space.read(message)` are sugar that delegate here.
 * Reads are fire-and-forget — providers handle them inside their `send`
 * action and the resolved value is `undefined`.
 *
 * Granularity is per-platform:
 *
 * - WhatsApp Business: per-message receipt via `markRead(target.id)`, which
 *   also marks every earlier message in the conversation as read.
 * - iMessage (remote): chat-level `chats.markRead(chatGuid)` — `target` only
 *   identifies the chat, and **every** unread message in it is marked read.
 *   Local mode rejects with `UnsupportedError` (warned and skipped).
 * - Telegram / Slack: silently no-op. Neither surfaces read state for bot
 *   conversations (Telegram bot chats are effectively auto-read), so the
 *   signal is vacuously satisfied — same best-effort contract as `typing`.
 */
export const readSchema = z.object({
  type: z.literal("read"),
  target: z.custom<Message>(isMessage, {
    message: "read target must be a Message",
  }),
});

export type Read = z.infer<typeof readSchema>;

export const asRead = (input: { target: Message }): Read =>
  readSchema.parse({ type: "read", ...input });
```

```ts
// read.ts:40-61
/**
 * Construct a `read` content value marking the conversation read up to
 * `target`.
 *
 * Only inbound messages (those received from a user) can be marked read;
 * calling this with an outbound target throws at build time so the misuse
 * surfaces before the send pipeline runs. The target is required (not
 * `Message | undefined` like `unsend`): read targets come from the inbound
 * stream, never from a chainable `send()` result.
 */
export function read(target: Message): ContentBuilder {
  return {
    build: async () => {
      if (target.direction !== "inbound") {
        throw new Error(
          `read() target must be an inbound message (got direction "${target.direction}", message id "${target.id}")`
        );
      }
      return asRead({ target });
    },
  };
}
```

**Design tension you'll hit:** `readSchema.target` requires `direction === "inbound"` *in the builder only* (schema doesn't enforce it). An **inbound** read receipt targets one of *your* **outbound** messages — the exact inverse. That's why a separate content arm (not a direction flip on `read`) is almost certainly right.

### `packages/core/src/content/group.ts` (complete, 52 lines)

```ts
// group.ts:1-34
import z from "zod";
import type { Message } from "../types/message";
import { resolveContents } from "./resolve";
import type { Content, ContentBuilder, ContentInput } from "./types";

const isMessage = (v: unknown): v is Message =>
  typeof v === "object" && v !== null && "id" in v && "content" in v;

/**
 * A `group` bundles multiple messages into one logical unit (e.g. an album
 * of images sent together). Each item is a full `Message` — addressable by
 * id, reactable via `.react()`, replyable via `.reply()`.
 *
 * Groups do not nest, and reactions cannot be group members. Enforced by the
 * `group()` builder; platforms may additionally reject unsupported item
 * content types at send time.
 */
export const groupSchema = z.object({
  type: z.literal("group"),
  items: z.array(z.custom<Message>(isMessage)).min(2),
});

export type Group = z.infer<typeof groupSchema>;

export const asGroup = (input: { items: Message[] }): Group =>
  groupSchema.parse({ type: "group", items: input.items });

// For outbound groups built via `group(attachment(...), ...)` the group items
// are not real Messages yet — they have no id, space, or methods until the
// provider's send path dispatches each one natively. We wrap the resolved
// content in a minimal shape that satisfies the `isMessage` guard and the
// providers read `item.content` directly.
const stubOutboundMessage = (content: Content): Message =>
  ({ id: "", content }) as unknown as Message;
```

```ts
// group.ts:36-52
export function group(
  ...items: [ContentInput, ContentInput, ...ContentInput[]]
): ContentBuilder {
  return {
    build: async () => {
      const resolved = await resolveContents(items);
      const members: Message[] = [];
      for (const item of resolved) {
        if (item.type === "group" || item.type === "reaction") {
          throw new Error(`group() cannot contain "${item.type}" items`);
        }
        members.push(stubOutboundMessage(item));
      }
      return asGroup({ items: members });
    },
  };
}
```

### `packages/core/src/content/typing.ts` (complete, 35 lines) — the minimal fire-and-forget shape

```ts
// typing.ts:1-35
import z from "zod";
import type { ContentBuilder } from "./types";

/**
 * A `typing` content value carries a typing-indicator signal — either
 * `"start"` or `"stop"`. Like `edit`, it's fire-and-forget: providers
 * dispatch on `content.type === "typing"` inside their `send()` action and
 * `space.send(typing(...))` resolves to `undefined`.
 *
 * `space.startTyping()` / `space.stopTyping()` / `space.responding()` are
 * sugar over `space.send(typing("start" | "stop"))`. Platforms that have no
 * typing-indicator API (e.g. WhatsApp Business) silently no-op so the
 * signal is best-effort everywhere.
 */
export const typingSchema = z.object({
  type: z.literal("typing"),
  state: z.enum(["start", "stop"]),
});

export type Typing = z.infer<typeof typingSchema>;

export const isTyping = (value: unknown): value is Typing =>
  typingSchema.safeParse(value).success;

/**
 * Construct a `typing` content value. Defaults to `"start"`.
 *
 * `space.send(typing())` is equivalent to `space.startTyping()`;
 * `space.send(typing("stop"))` is equivalent to `space.stopTyping()`.
 */
export function typing(state: "start" | "stop" = "start"): ContentBuilder {
  return {
    build: async () => typingSchema.parse({ type: "typing", state }),
  };
}
```

### Bonus: `membership.ts` — the canonical **bidirectional** doc-comment convention

`/Users/ryanzhu/Projects/spectrum-ts/packages/core/src/content/membership.ts:16-21` is the phrasing you should mirror for an inbound-capable type:

```ts
 * Bidirectional: providers also surface platform membership events as
 * inbound `Message`s carrying this content. `message.sender` is the acting
 * user — who added/removed the members — and may be `undefined` when the
 * platform recorded no actor. For `leaveSpace` the sender is the leaver
 * (the content carries no `members`). The agent's own actions are
 * suppressed: `space.add(...)` does not echo back as an inbound event.
```

Same in `rename.ts:12-14`:
```ts
 * Bidirectional: providers also surface platform rename events as inbound
 * `Message`s carrying this content; `message.sender` is the user who renamed
 * the chat (may be `undefined` when the platform recorded no actor).
```

