// types.ts:28-86
// Content values describe state changes and are direction-agnostic — the same
// discriminants serve `space.send(...)` and inbound Messages (e.g. `reaction`
// is both sent by the agent and constructed by providers when a user reacts;
// membership/rename/avatar likewise). The Message envelope carries `direction`
// and the actor (`sender`); names stay flat and mood-neutral, not command- or
// event-flavored.
//
// `baseContentSchema` is everything except `reply`, `edit`, `unsend`, and
// `read`. It exists so the inner content of a `Reply` (and `Edit`) can be
// typed against this non-circular union without `Content` referencing itself
// via `Reply.content` / `Edit.content`. Both builders reject nested wrapping
// in their reject-lists, so the looser typing here is also correct.
// `unsend` and `read` carry no inner content but stay out of the base union
// too, so reply/edit cannot statically wrap them.
const baseContentSchemas = [
  textSchema,
  markdownSchema,
  streamTextSchema,
  customSchema,
  attachmentSchema,
  contactSchema,
  voiceSchema,
  richlinkSchema,
  appSchema,
  reactionSchema,
  groupSchema,
  pollSchema,
  pollOptionSchema,
  messageEffectSchema,
  typingSchema,
  renameSchema,
  avatarSchema,
  addMemberSchema,
  removeMemberSchema,
  leaveSpaceSchema,
] as const;

export const baseContentSchema = z.discriminatedUnion(
  "type",
  baseContentSchemas
);

export type BaseContent = z.infer<typeof baseContentSchema>;

export const contentSchema = z.discriminatedUnion("type", [
  ...baseContentSchemas,
  replySchema,
  editSchema,
  unsendSchema,
  readSchema,
]);

export type Content = z.infer<typeof contentSchema>;

export interface ContentBuilder {
  build(): Promise<Content>;
}

export type ContentInput = string | ContentBuilder;
```

