### `mapContent` — verbatim (`packages/core/src/webhook/deserialize.ts:125-174`)

```ts
const mapContent = (
  content: SlimContent,
  platform: string,
  spaceRef: SpaceRef,
  ctx: DeserializeContext
): Content => {
  const raw = content as Record<string, unknown>;
  switch (content.type) {
    case "text":
      return { type: "text", text: asString(raw.text) };
    case "richlink":
      // Outbound-only content type; inbound URLs always surface as text.
      return { type: "text", text: asString(raw.url) };
    case "contact":
      return deserializeContact(raw);
    case "reaction":
      return deserializeReaction(raw, spaceRef);
    case "reply":
      return deserializeReply(raw, platform, spaceRef, ctx);
    case "group":
      return deserializeGroup(raw, platform, spaceRef, ctx);
    case "attachment":
      return deserializeAttachment(raw, platform, spaceRef, ctx);
    case "voice":
      return deserializeVoice(raw, platform, spaceRef, ctx);
    case "addMember":
      return addMemberSchema.parse({
        type: "addMember",
        members: memberStrings(raw.members),
      });
    case "removeMember":
      return removeMemberSchema.parse({
        type: "removeMember",
        members: memberStrings(raw.members),
      });
    case "leaveSpace":
      // The leaver rides on the envelope (`message.sender`), not the content.
      return leaveSpaceSchema.parse({ type: "leaveSpace" });
    case "rename":
      // Empty displayName fails min(1) and degrades the delivery to `custom`.
      return renameSchema.parse({
        type: "rename",
        displayName: asString(raw.displayName),
      });
    case "avatar":
      return deserializeAvatar(raw, platform);
    default:
      return asCustom(content);
  }
};
```

**Consequence:** without a new `case`, an inbound read receipt arriving over the native webhook silently degrades to `{ type: "custom", raw: {…} }`. The consumer's `switch` never matches. This is the single most important thing to add for cloud round-trip survival.

The wrapping error boundary (`deserialize.ts:110-123`):
```ts
// A wire content arm we couldn't map cleanly still reaches the handler as
// `custom` (carrying the original JSON) rather than failing the whole delivery.
const deserializeContent = (
  content: SlimContent,
  platform: string,
  spaceRef: SpaceRef,
  ctx: DeserializeContext
): Content => {
  try {
    return mapContent(content, platform, spaceRef, ctx);
  } catch {
    return asCustom(content);
  }
};
```

The envelope mapper — note it **hardcodes `direction: "inbound"`** (`deserialize.ts:81-105`):
```ts
export function deserializeSpectrumMessage(
  envelope: SlimEnvelope,
  ctx: DeserializeContext
): DeserializeResult | null {
  if (envelope.event !== MESSAGES_EVENT) {
    return null;
  }
  const message = envelope.message;
  const platform = resolvePlatform(message);
  if (!platform) {
    return null;
  }
  const spaceRef: SpaceRef = { ...message.space };
  return {
    platform,
    record: {
      id: message.id,
      direction: "inbound",
      content: deserializeContent(message.content, platform, spaceRef, ctx),
      space: spaceRef,
      sender: message.sender ? { ...message.sender } : undefined,
      timestamp: asOptionalDate(message.timestamp),
    },
  };
}
```

The target-record helper you'd reuse (`deserialize.ts:295-309`) — **read the comment carefully, targets arrive content-less**:
```ts
const buildTargetRecord = (
  target: unknown,
  spaceRef: SpaceRef
): ProviderMessageRecord => {
  const ref = (isRecord(target) ? target : {}) as Partial<SlimMessageRef>;
  return {
    id: asString(ref.id),
    // The target's full content is not delivered; the 80-char `contentPreview`
    // (text targets only) is the best available stand-in.
    content: { type: "text", text: asString(ref.contentPreview) },
    space: { ...spaceRef },
    sender: ref.sender ? { ...ref.sender } : undefined,
    timestamp: asOptionalDate(ref.timestamp),
  };
};
```
And the reaction mapper showing the raw-record handoff pattern (`deserialize.ts:270-279`):
```ts
const deserializeReaction = (
  raw: Record<string, unknown>,
  spaceRef: SpaceRef
): Content =>
  // `target` is a raw record; `wrapNestedContent` wraps it into a Message.
  ({
    type: "reaction",
    emoji: asString(raw.emoji),
    target: buildTargetRecord(raw.target, spaceRef),
  }) as unknown as Content;
```
⚠️ `buildTargetRecord` sets no `direction`, so `wrapNestedContent` decides. For a read receipt whose target is outbound, you'd need either `direction: "outbound"` on the target record or an `"outbound"` arm in `wrapNestedContent` (per `wrapProviderMessage`'s `rawDirection(raw) ?? direction`, `build.ts:483-488, 507`).

