    processMissed: (event) =>
      event.type === "catchup.complete"
        ? Promise.resolve(toCatchUpCompleteItem(event))
        : skipUnmappable(/* …same as processLive… */),
    subscribeLive: (cursor) =>
      withClose(client.messages.subscribeEvents(), cursor),
