import { app, attachment, edit, markdown, poll, reaction, Spectrum, text, unsend } from "spectrum-ts";
import { telegram, whatsappBusiness } from "spectrum-ts/providers";
import { background, imessage } from "@spectrum-ts/imessage";
import { terminal } from "spectrum-ts/providers/terminal";
import { addMember, removeMember } from "@spectrum-ts/core";
import { spec } from "node:test/reporters";

// Simulate an LLM token stream — swap this for `result.textStream` from the
// OpenAI / Anthropic / Vercel AI SDK and `streamText(stream)` just works.
async function* fakeTokenStream(text: string): AsyncIterable<string> {
  for (const word of text.split(" ")) {

    await new Promise((resolve) => setTimeout(resolve, 200));
    yield `${word} `;
  }
}

// const spectrum = await Spectrum({
//   projectId: "d7f296f8-d39b-40b1-80c1-19ae882efafd",
//   projectSecret: "REDACTED",
//   providers: [imessage.config()],
//   options: {
//     flattenGroups: true,
//   }
//   // telemetry: true,
// });

const spectrum = await Spectrum({
  projectId: "13764d32-4b46-41ba-bbc8-eb6520504576",
  projectSecret: "REDACTED",
  providers: [imessage.config()],
  telemetry: true,
});

console.log(spectrum.config);

// const space = await imessage(spectrum).space.create(["+13322593374", "+15103658086"])
// const msg = await space.send("hello1");
// await space.unsend(msg);

for await (const [space, message] of spectrum.messages) {
  console.log("[received]", message.content.type);

  switch (message.content.type) {
    case "reaction": {
      console.log("  reaction:", message.content.emoji, message.content.target.id);
      break;
    }
    case "read": {
      console.log("  read:", message.content.target.content);
      break;
    }
    case "text": {
      console.log("  text:", message.content.text);

      // await space.send(removeMember("+15103658086"))

      // console.log(space)
      // console.log(message.sender)

      // const msg = await space.send(markdown("yo **hi** *ultra* `hihihihi`"));
      const msg = await space.send("hi");
      // await space.send(edit("hello", msg));
      // await imessage(space).send(app("https://www.desmos.com/scientific", {live: true}));
      // await message.react("❤️");
      // await space.send(text(fakeTokenStream("This is a streamed response from the AI model. This is a streamed response from the AI model.")));
      // await space.send(attachment("/Users/ryanzhu/Downloads/CleanShot 2026-05-19 at 16.18.22@2x.png"));

      // Stream a reply: the first chunk goes out as a real message, then it's
      // edited in place as more "tokens" arrive (iMessage remote only).

      // With a real model, pass whatever the SDK returns — e.g. the Vercel AI SDK:
      //   import { streamText as aiStreamText } from "ai";
      //   const result = aiStreamText({ model: openai("gpt-4o"), prompt: message.content.text });
      //   await space.send(streamText(result)); // result.textStream is auto-detected

      // Reply to any inbound text with an `app` card. The caller passes only
      // the URL — it routes through Spectrum's own mini app, and the layout
      // (title / description / image) is parsed from the URL's link metadata.
      // On non-iMessage platforms the same content degrades to the bare URL.
      // await space.send(
      //   app("https://manus.im/")
      // );

      console.log("[sent] mini app");
      break;
    }
    case "attachment": {
      console.log("  attachment:", message.content.name);
      console.log("  attachment id:", message.content.id);

      break;
    }
    case "poll_option": {
      const action = message.content.selected ? "selected" : "deselected";
      console.log(
        `  ${action}: "${message.content.option.title}" (poll: "${message.content.poll.title}")`
      );
      break;
    }
    default:
      console.log("  raw:", message.content);
      break;
  }
}

